import React, { useState, useEffect } from 'react';
import axios from 'axios';

const QRCodeViewer = () => {
  const [qrCode, setQrCode] = useState('');
  const productId = '1'; // Replace with actual MongoDB product _id

  useEffect(() => {
    const fetchQRCode = async () => {
      try {
        const response = await axios.get(`http://localhost:5555/product/${productId}/qrcode`);
        setQrCode(response.data.qrCode);
      } catch (error) {
        console.error('Error fetching QR code:', error);
      }
    };

    fetchQRCode();
  }, []);

  return (
    <div style={{ textAlign: 'center', marginTop: '2rem' }}>
      <h2>QR Code for Product</h2>
      {qrCode ? <img src={qrCode} alt="QR Code" /> : <p>Loading...</p>}
    </div>
  );
};

export default QRCodeViewer;
